// New method to check declared property inheritance
public boolean checkDeclaredPropertyInheritance(Object obj, String property) {
    // Start with the given object
    Class<?> clazz = obj.getClass();
    // Check each class in the inheritance chain
    while (clazz != null) {
        try {
            // Check if the property is declared in the current class
            clazz.getDeclaredField(property);
            return true;
        } catch (NoSuchFieldException e) {
            // Move up the inheritance chain
            clazz = clazz.getSuperclass();
        }
    }
    // Property not found in the inheritance chain
    return false;
}
